#include "daxa_view_depth_common.hpp"
#include <cstring>
using namespace view_app;
namespace {
constexpr const char* suffix[]={".lr_disparity.f32",".lr_confidence.f32",".lr_validity.u32",".depth.f32",".metric_confidence.f32",".metric_validity.u32",".provenance.u32",".source_ids.i64",".age_ns.i64"};
struct Observations {
    std::array<std::vector<std::byte>,9> bytes;std::array<std::string,9> hashes;
    Observations(std::string const& prefix,size_t n,uint32_t width,DaxaPreprocessReadback const& images){for(unsigned p=0;p<9;++p){auto path=prefix+suffix[p];size_t count=2*n*(p<7?4:8);check(std::filesystem::file_size(path)==count,"diagnostic observation extent mismatch");bytes[p].resize(count);std::ifstream in(path,std::ios::binary);in.read(reinterpret_cast<char*>(bytes[p].data()),std::streamsize(count));check(bool(in),"diagnostic observation read failed");hashes[p]=daxa_preprocess_file_sha256(path);}
        auto scalar=[&]<class T>(unsigned plane,size_t i){T out;std::memcpy(&out,bytes[plane].data()+i*sizeof(T),sizeof(T));return out;};
        for(size_t i=0;i<2*n;++i){float disparity=scalar.operator()<float>(0,i),confidence=scalar.operator()<float>(1,i),z=scalar.operator()<float>(3,i),metric_conf=scalar.operator()<float>(4,i);auto lr=scalar.operator()<uint32_t>(2,i),valid=scalar.operator()<uint32_t>(5,i),prov=scalar.operator()<uint32_t>(6,i);auto id=scalar.operator()<int64_t>(7,i),age=scalar.operator()<int64_t>(8,i);check(lr<=1&&valid<=1,"binary fixture validity required");check(lr?(std::isfinite(disparity)&&std::isfinite(confidence)&&confidence>=0&&confidence<=1):(std::bit_cast<uint32_t>(disparity)==0x7fc00000&&confidence==0),"fixture LR defaults/domain mismatch");check(valid?(lr&&std::isfinite(z)&&z>0&&std::isfinite(metric_conf)&&metric_conf>=0&&metric_conf<=1&&prov>=1&&prov<=5&&id>=0&&age>=0):(std::bit_cast<uint32_t>(z)==0x7fc00000&&metric_conf==0&&prov==0&&id==-1&&age==0),"fixture metric defaults/domain mismatch");if(valid){unsigned eye=unsigned(i/n);size_t local=i%n;double x=std::floor(double(local%width)+(eye?double(disparity):-double(disparity))+.5);check(std::isfinite(x)&&x>=0&&x<double(width),"fixture metric correspondence outside source");auto target=(local/width)*width+size_t(x);check(images.planes[6+eye][local]&&images.planes[7-eye][target],"fixture metric requires qualified source/correspondence remap support");}}
    }
    void verify(std::string const& prefix)const{for(unsigned p=0;p<9;++p)check(daxa_preprocess_file_sha256(prefix+suffix[p])==hashes[p],"fixture observations changed during run");}
    // Exclusive diagnostic Frame: no view exists and producer completion precedes
    // transfer. Its original completion is insufficient for this later upload.
    void replace_once(DaxaDepthPipeline::Frame const& frame,DaxaFoundation& context)const{
        frame.wait();auto& d=context.device;std::vector<daxa::MemoryBlock> memory;std::vector<daxa::BufferId> staging;auto recorder=d.create_command_recorder({.name="synthetic exclusive observation replacement outside timing"});recorder.pipeline_barrier({.src_access=daxa::AccessConsts::HOST_WRITE|daxa::AccessConsts::COMPUTE_SHADER_WRITE,.dst_access=daxa::AccessConsts::TRANSFER_READ|daxa::AccessConsts::TRANSFER_WRITE});for(unsigned p=0;p<9;++p){daxa::BufferInfo info{.size=bytes[p].size(),.name="synthetic observation staging"};auto block=d.create_memory({.requirements=context.coherent_readback_requirements(info),.flags=daxa::MemoryFlagBits::HOST_ACCESS_RANDOM});auto id=d.create_buffer_from_memory_block({.buffer_info=info,.memory_block=block});memory.push_back(std::move(block));staging.push_back(id);std::memcpy(d.buffer_host_address(id).value(),bytes[p].data(),bytes[p].size());recorder.copy_buffer_to_buffer({.src_buffer=id,.dst_buffer=frame.buffer(DaxaDepthPlane(p)),.size=bytes[p].size()});}recorder.pipeline_barrier({.src_access=daxa::AccessConsts::TRANSFER_WRITE,.dst_access=daxa::AccessConsts::COMPUTE_SHADER_READ});auto command=recorder.complete_current_commands();d.submit_commands({.command_lists={&command,1}});auto replacement_submit=d.latest_queue_submit_index(daxa::QUEUE_MAIN);d.wait_on_submit({.queue=daxa::QUEUE_MAIN,.queue_submit_index=replacement_submit,.timeout=30'000'000'000ull});for(auto id:staging)d.destroy_buffer(id);d.collect_garbage();
    }
};
}
int main(int argc,char** argv){try{
    if(getter(argc,argv))return 0;Options options(argc,argv,true);Prepared prepared(options,true);check(prepared.source->device_identity.find("synthetic")!=std::string::npos,"fixture record must explicitly identify synthetic capture");auto prefix=options.values.at("--observations-prefix");auto images=daxa_preprocess_reference(*prepared.source,prepared.fixture.rectification);Observations observations(prefix,size_t(prepared.config.source_width)*prepared.config.source_height,prepared.config.source_width,images);
    auto context=std::make_shared<DaxaFoundation>(options.validation);auto pipeline=std::make_unique<DaxaDepthPipeline>(prepared.fixture.rectification,prepared.depth,context,prepared.source);auto input=pipeline->enqueue(prepared.source);observations.replace_once(input,*context);auto view=std::make_unique<DaxaView>(prepared.config,prepared.view,context,input,prepared.depth.slots);check(view->can_project(),"fresh fixture view capacity");auto output=view->project(input);output.wait();auto exported=view->readback(output);dump(exported,options.values.at("--dump-prefix"));auto result=report(prepared,true);coverage(result,exported);result["synthetic_capture"]=true;result["diagnostic_observation_sha256"]=observations.hashes;result["replacement_transfer_completion_waited"]=true;result["validation_requested"]=options.validation;output={};view->collect();view.reset();input={};pipeline->drain();pipeline.reset();result["device"]=json::parse(context->report());context->close();check(context->validation_errors==0&&context->validation_warnings==0,"synthetic view validation failed through teardown");result["validation_errors_after_teardown"]=context->validation_errors.load();result["validation_warnings_after_teardown"]=context->validation_warnings.load();observations.verify(prefix);prepared.verify_inputs(options);finish(options,result);return 0;
}catch(std::exception const& e){std::cerr<<"daxa_view_depth_fixture: "<<e.what()<<'\n';return 1;}}
